{%- macro notes_block(remarks, terms) -%}
{%- set rm = (remarks or '') | trim -%}
{%- set tx = (terms or '') | replace('<p><br></p>', '') -%}
{%- set nn = namespace(txt='', img='') -%}
{%- set _parts = tx.split('<img') -%}
{%- set nn.txt = _parts[0] -%}
{%- for pt in _parts[1:] -%}
  {%- set _ab = pt.split('>', 1) -%}
  {%- set nn.img = nn.img ~ '<img' ~ _ab[0] ~ '>' -%}
  {%- set nn.txt = nn.txt ~ (_ab[1] if _ab | length > 1 else '') -%}
{%- endfor -%}
{%- set has_rm = rm and rm != 'No Remarks' -%}
{%- set has_tx = (nn.txt | striptags | trim) != '' -%}
{%- if has_rm or has_tx or nn.img %}
<table class="note">
  <colgroup><col>{% if nn.img %}<col style="width:48%">{% endif %}</colgroup>
  <tr>
    <td>
      {%- if has_rm %}{%- set rm_ar = rm | select('ge', '\u0600') | select('le', '\u06ff') | list | length > 0 -%}
      {{ lbl('Remarks', 'Remarks') }}<div class="rmv{{ '' if rm_ar else ' ltrv' }}">{{ rm }}</div>{% endif %}
      {%- if has_tx %}{{ nn.txt }}{% endif %}
    </td>
    {%- if nn.img %}<td class="stamp">{{ nn.img }}</td>{% endif %}
  </tr>
</table>
{%- endif -%}
{%- endmacro -%}




{%- macro dir_cls(l) -%}
{%- set fs = namespace(d='') -%}
{%- for ch in l -%}{%- if not fs.d -%}{%- if ('A' <= ch <= 'Z') or ('a' <= ch <= 'z') -%}{%- set fs.d = 'l' -%}{%- elif '\u0600' <= ch <= '\u06ff' -%}{%- set fs.d = 'r' -%}{%- endif -%}{%- endif -%}{%- endfor -%}
{{- ' ltrv' if fs.d == 'l' else '' -}}
{%- endmacro -%}
{%- macro text_block(t_key, t_en, text, ctx=none) -%}
{%- set src = (text or '') | replace('\r', '') | replace('\t', ' ') | trim -%}
{%- if src %}
{%- set tb = namespace(lines=[], n=0, recs=[], cur=[], gap=false) -%}
{%- for ln in src.split('\n') -%}{%- set l = ln.split() | join(' ') -%}{%- set tb.lines = tb.lines + [l] -%}{%- if l -%}{%- set tb.n = tb.n + 1 -%}{%- endif -%}{%- endfor -%}
<table class="txt{{ ' cmp' if tb.n > 30 else '' }}">
  <colgroup><col></colgroup>
  <tr><td class="plabel">{{ lbl(t_key, t_en, ctx=ctx) }}</td></tr>
  <tr><td>
  {%- if tb.n > 30 -%}
    {%- for l in tb.lines -%}
      {%- if not l or not (l | replace('-', '') | replace('_', '') | replace('=', '') | replace('*', '') | trim) -%}
        {%- if tb.cur -%}{%- set tb.recs = tb.recs + [tb.cur] -%}{%- set tb.cur = [] -%}{%- endif -%}
      {%- else -%}{%- set tb.cur = tb.cur + [l] -%}
      {%- endif -%}
    {%- endfor -%}
    {%- if tb.cur -%}{%- set tb.recs = tb.recs + [tb.cur] -%}{%- endif -%}
    {%- for r in tb.recs %}
    <div class="ln{{ dir_cls(r[0]) }}">{% for l in r %}{% if not loop.first %}<span class="sep"> | </span>{% endif %}{{ l | e }}{% endfor %}</div>
    {%- endfor -%}
  {%- else -%}
    {%- for l in tb.lines -%}
      {%- if l %}
    <div class="ln{{ dir_cls(l) }}{{ ' gap' if tb.gap else '' }}">{{ l | e }}</div>
        {%- set tb.gap = false -%}
      {%- else -%}{%- set tb.gap = true -%}
      {%- endif -%}
    {%- endfor -%}
  {%- endif %}
  </td></tr>
</table>
{%- endif -%}
{%- endmacro -%}


{%- macro bipara_block(t_key, t_en, text, ctx=none) -%}
{%- set a = _(text, lang='ar', context=ctx) -%}
<table class="bip">
  <colgroup><col style="width:50%"><col style="width:50%"></colgroup>
  <tr><td colspan="2" class="plabel">{{ lbl(t_key, t_en, ctx=ctx) }}</td></tr>
  {%- if a != text %}
  <tr><td class="a">{{ a }}</td><td class="e ltr">{{ text }}</td></tr>
  {%- else %}
  <tr><td class="e ltr" colspan="2">{{ text }}</td></tr>
  {%- endif %}
</table>
{%- endmacro -%}


{%- macro signoff_block(signers, lines) -%}
